    // About Page
    "about.title": "O společnosti",
    "about.subtitle":
      "Spojujeme kupující a prodejce automobilů v celé České republice",
    "about.storyTitle": "Náš příběh",
    "about.storyP1":
      "NNAuto vzniklo v roce 2024 s jasnou vizí: vytvořit nejlepší platformu pro nákup a prodej automobilů v České republice. Naši zakladatelé, nadšenci do automobilů s letitými zkušenostmi v automotive průmyslu, viděli potřebu modernějšího, transparentnějšího a uživatelsky příjemnějšího řešení.",
    "about.storyP2":
      "Od prvních dnů jsme se zaměřili na kvalitu nad kvantitou. Každý inzerát je pečlivě kontrolován, ověřujeme identitu prodejců a garantujeme pravdivost údajů. Tím se odlišujeme od konkurence a získáváme důvěru tisíců uživatelů.",
    "about.storyP3":
      "Dnes jsme hrdí, že NNAuto je domovem pro tisíce prémiových automobilů a spojuje desítky tisíc spokojených kupujících a prodejců každý měsíc. A to je teprve začátek naší cesty.",
    "about.missionTitle": "Naše mise",
    "cebia.title": "Kontrola VIN (Cebia)",
    "cebia.description":
      "Pokud je report dostupný, můžete objednat kontrolu a stáhnout PDF.",
    "cebia.loading": "Ověřuji dostupnost reportu…",
    "cebia.orderCheck": "Objednat kontrolu",
    "cebia.creating": "Vytvářím report…",
    "cebia.openPdf": "Otevřít PDF",
    "cebia.unavailable": "Report pro toto VIN není dostupný",
    "cebia.error": "Chyba kontroly. Zkuste to prosím znovu",
    "cebia.requiresListingVin": "Cebia je dostupná jen u inzerátů s platným VIN od majitele.",
    "about.missionP1":
      "Věříme, že nákup nebo prodej automobilu by měl být jednoduchý, bezpečný a příjemný zážitek. Proto budujeme platformu, která spojuje moderní technologie s osobním přístupem. Chceme, aby každý zákazník našel přesně to, co hledá - ať už je to rodinné SUV, sportovní kupé nebo užitkový vůz.",
    "about.trustTitle": "Důvěra",
    "about.trustDesc":
      "Ověřujeme každý inzerát a chráníme vaše údaje moderními bezpečnostními technologiemi.",
    "about.communityTitle": "Komunita",
    "about.communityDesc":
      "Budujeme komunitu automotive nadšenců, kde se lidé setkávají a sdílejí své vášně.",
    "about.valuesTitle": "Naše hodnoty",
    "about.value1Title": "Transparentnost",
    "about.value1Desc":
      "Žádné skryté poplatky, žádné nejasnosti. Vše, co potřebujete vědět, najdete přímo v inzerátu.",
    "about.value2Title": "Bezpečnost",
    "about.value2Desc":
      "Ochrana vašich osobních údajů a bezpečnost transakcí je pro nás prioritou číslo jedna.",
    "about.value3Title": "Kvalita",
    "about.value3Desc":
      "Pečlivě kontrolujeme každý inzerát, aby naši uživatelé měli jistotu v kvalitu nabízených automobilů.",
    "about.value4Title": "Inovace",
    "about.value4Desc":
      "Neustále vylepšujeme naši platformu podle zpětné vazby od uživatelů a nejnovějších technologických trendů.",
    "about.statsTitle": "NNAuto v číslech",
    "about.stat1": "Aktivních inzerátů",
    "about.stat2": "Spokojených uživatelů",
    "about.stat3": "Úspěšnost prodeje",
    "about.stat4": "Podpora",
    "about.teamTitle": "Náš tým",
    "about.teamP1":
      "Za NNAuto stojí tým nadšených profesionálů s bohatými zkušenostmi v automotive průmyslu, IT technologiích a zákaznickém servisu. Každý den pracujeme na tom, aby naše platforma byla ještě lepší, rychlejší a uživatelsky příjemnější.",
    "about.teamP2":
      "Náš tým podpory je k dispozici 24/7, protože víme, že nákup nebo prodej automobilu nečeká na pracovní dobu. Jsme tady pro vás kdykoliv potřebujete pomoc nebo radu.",
    "about.ctaTitle": "Máte otázky?",
    "about.ctaDesc":
      "Rádi vám pomůžeme s čímkoliv. Kontaktujte nás emailem nebo telefonem.",
    "about.ctaEmail": "Napište nám",
    "about.ctaPhone": "+420 123 456 789",

    // Contact Page
    "contact.title": "Kontaktujte nás",
