    // Tips Page
    "tips.title": "Tipy pro úspěšný prodej",
    "tips.subtitle": "Praktické rady, jak rychle a výhodně prodat své auto",
    "tips.photosTitle": "Kvalitní fotografie",
    "tips.photosIntro":
      "Fotografie jsou první, co kupující vidí. Kvalitní snímky mohou zvýšit vaše šance na prodej až o 80%.",
    "tips.photo1Title": "Čisté auto ze všech stran",
    "tips.photo1Desc":
      "Před focením auto důkladně umyjte a vyleštěte. Nafocte ze všech 4 stran, zepředu i zezadu.",
    "tips.photo2Title": "Dobré osvětlení",
    "tips.photo2Desc":
      "Fotografie pořizujte při denním světle, nejlépe venku. Vyhněte se focení v noci nebo v tmavé garáži.",
    "tips.photo3Title": "Detail interiéru",
    "tips.photo3Desc":
      "Ukažte palubní desku, sedadla, volant a zavazadlový prostor. Vnitřek by měl být čistý a uklizený.",
    "tips.photo4Title": "Technické detaily",
    "tips.photo4Desc":
      "Přidejte fotky motoru, počítadla kilometrů a případných poškození. Buďte transparentní.",
    "tips.descriptionTitle": "Popis inzerátu",
    "tips.descriptionIntro":
      "Kvalitní popis pomáhá kupujícím rozhodnout se rychleji a snižuje zbytečné dotazy.",
    "tips.desc1Title": "Buďte upřímní",
    "tips.desc1Desc":
      "Uveďte všechny závady a historii vozu. Transparentnost buduje důvěru a urychluje prodej.",
    "tips.desc2Title": "Technické údaje",
    "tips.desc2Desc":
      "Jasně specifikujte rok výroby, nájezd km, typ paliva, výbavu a servisní historii.",
    "tips.desc3Title": "Unikátní vlastnosti",
    "tips.desc3Desc":
      "Zdůrazněte výhody - nové pneumatiky, čerstvá STK, garáž, servisní knížka, jeden majitel atd.",
    "tips.pricingTitle": "Stanovení ceny",
    "tips.pricingIntro": "Správná cena je klíčem k rychlému prodeji.",
    "tips.price1Title": "Srovnejte s trhem",
    "tips.price1Desc":
      "Podívejte se na podobné inzeráty stejného modelu a roku výroby. Nastavte konkurenceschopnou cenu.",
    "tips.price2Title": "Nechte prostor na vyjednávání",
    "tips.price2Desc":
      "Kupující obvykle očekávají možnost smlouvat. Přidejte 5-10% nad vaši minimální přijatelnou cenu.",
    "tips.price3Title": "Aktualizujte cenu",
    "tips.price3Desc":
      "Pokud auto nejde na odbyt, snižte cenu každé 2-3 týdny. Reagujte na poptávku.",
    "tips.communicationTitle": "Komunikace s kupujícími",
    "tips.comm1Title": "Rychlá odpověď",
    "tips.comm1Desc":
      "Odpovídejte na dotazy do 24 hodin. Rychlá reakce ukazuje zájem a profesionalitu.",
    "tips.comm2Title": "Flexibilní prohlídky",
    "tips.comm2Desc":
      "Nabídněte několik termínů prohlídky. Vyjděte kupujícím vstříc při plánování.",
    "tips.comm3Title": "Profesionální přístup",
    "tips.comm3Desc":
      "Buďte slušní, trpěliví a ochotní odpovědět na všechny otázky. První dojem rozhoduje.",
