    // About Page
    "about.title": "Про компанію",
    "about.subtitle":
      "Ми з'єднуємо покупців та продавців автомобілів у всій Чехії",
    "about.storyTitle": "Наша історія",
    "about.storyP1":
      "NNAuto було створено у 2024 році з чіткою візією: створити найкращу платформу для купівлі та продажу автомобілів у Чехії. Наші засновники, автомобільні ентузіасти з багаторічним досвідом в automotive індустрії, побачили потребу в більш сучасному, прозорому та зручному рішенні.",
    "about.storyP2":
      "З перших днів ми зосередилися на якості, а не на кількості. Кожне оголошення ретельно перевіряється, ми підтверджуємо особу продавців та гарантуємо достовірність даних. Це відрізняє нас від конкурентів і допомагає завоювати довіру тисяч користувачів.",
    "about.storyP3":
      "Сьогодні ми пишаємося тим, що NNAuto є домом для тисяч преміум-автомобілів та з'єднує десятки тисяч задоволених покупців та продавців щомісяця. І це лише початок нашого шляху.",
    "about.missionTitle": "Наша місія",
    "about.missionP1":
      "Ми віримо, що купівля або продаж автомобіля має бути простим, безпечним та приємним досвідом. Тому ми будуємо платформу, що поєднує сучасні технології з персональним підходом. Ми хочемо, щоб кожен клієнт знайшов саме те, що шукає - чи то сімейний SUV, спортивне купе або комерційна машина.",
    "about.trustTitle": "Довіра",
    "about.trustDesc":
      "Ми перевіряємо кожне оголошення та захищаємо ваші дані сучасними технологіями безпеки.",
    "about.communityTitle": "Спільнота",
    "about.communityDesc":
      "Ми будуємо спільноту автомобільних ентузіастів, де люди зустрічаються та діляться своїми захопленнями.",
    "about.valuesTitle": "Наші цінності",
    "about.value1Title": "Прозорість",
    "about.value1Desc":
      "Ніяких прихованих комісій, ніяких неясностей. Все, що вам потрібно знати, ви знайдете прямо в оголошенні.",
    "about.value2Title": "Безпека",
    "about.value2Desc":
      "Захист ваших персональних даних та безпека транзакцій є нашим пріоритетом номер один.",
    "about.value3Title": "Якість",
    "about.value3Desc":
      "Ми ретельно перевіряємо кожне оголошення, щоб наші користувачі мали впевненість у якості пропонованих автомобілів.",
    "about.value4Title": "Інновації",
    "about.value4Desc":
      "Ми постійно покращуємо нашу платформу на основі відгуків користувачів та найновіших технологічних трендів.",
    "about.statsTitle": "NNAuto у цифрах",
    "about.stat1": "Активних оголошень",
    "about.stat2": "Задоволених користувачів",
    "about.stat3": "Успішність продажу",
    "about.stat4": "Підтримка",
    "about.teamTitle": "Наша команда",
    "about.teamP1":
      "За NNAuto стоїть команда захоплених професіоналів з багатим досвідом в automotive індустрії, IT технологіях та обслуговуванні клієнтів. Щодня ми працюємо над тим, щоб наша платформа була ще кращою, швидшою та зручнішою.",
    "about.teamP2":
      "Наша команда підтримки доступна 24/7, тому що ми знаємо, що купівля або продаж автомобіля не чекає робочого часу. Ми тут для вас, коли вам потрібна допомога чи порада.",
    "about.ctaTitle": "Маєте питання?",
    "about.ctaDesc":
      "Ми раді допомогти вам з будь-чим. Зв'яжіться з нами електронною поштою або телефоном.",
    "about.ctaEmail": "Напишіть нам",
    "about.ctaPhone": "+420 123 456 789",

