    // About Page
    "about.title": "About Us",
    "about.subtitle":
      "Connecting car buyers and sellers across the Czech Republic",
    "about.storyTitle": "Our Story",
    "about.storyP1":
      "NNAuto was founded in 2024 with a clear vision: to create the best platform for buying and selling cars in the Czech Republic. Our founders, car enthusiasts with years of experience in the automotive industry, saw the need for a more modern, transparent, and user-friendly solution.",
    "about.storyP2":
      "From day one, we focused on quality over quantity. Every listing is carefully reviewed, we verify seller identities and guarantee data accuracy. This sets us apart from competitors and earns the trust of thousands of users.",
    "about.storyP3":
      "Today, we're proud that NNAuto is home to thousands of premium cars and connects tens of thousands of satisfied buyers and sellers every month. And this is just the beginning of our journey.",
    "about.missionTitle": "Our Mission",
    "about.missionP1":
      "We believe that buying or selling a car should be simple, safe, and enjoyable. That's why we're building a platform that combines modern technology with personal service. We want every customer to find exactly what they're looking for - whether it's a family SUV, sports coupe, or commercial vehicle.",
    "about.trustTitle": "Trust",
    "about.trustDesc":
      "We verify every listing and protect your data with modern security technologies.",
    "about.communityTitle": "Community",
    "about.communityDesc":
      "We're building a community of automotive enthusiasts where people meet and share their passions.",
    "about.valuesTitle": "Our Values",
    "about.value1Title": "Transparency",
    "about.value1Desc":
      "No hidden fees, no ambiguities. Everything you need to know is right in the listing.",
    "about.value2Title": "Security",
    "about.value2Desc":
      "Protecting your personal data and transaction security is our number one priority.",
    "about.value3Title": "Quality",
    "about.value3Desc":
      "We carefully review every listing so our users can be confident in the quality of offered cars.",
    "about.value4Title": "Innovation",
    "about.value4Desc":
      "We constantly improve our platform based on user feedback and the latest technology trends.",
    "about.statsTitle": "NNAuto in Numbers",
    "about.stat1": "Active Listings",
    "about.stat2": "Happy Users",
    "about.stat3": "Sale Success Rate",
    "about.stat4": "Support",
    "about.teamTitle": "Our Team",
    "about.teamP1":
      "Behind NNAuto is a team of passionate professionals with extensive experience in the automotive industry, IT technologies, and customer service. Every day we work to make our platform even better, faster, and more user-friendly.",
    "about.teamP2":
      "Our support team is available 24/7 because we know that buying or selling a car doesn't wait for business hours. We're here for you whenever you need help or advice.",
    "about.ctaTitle": "Have Questions?",
    "about.ctaDesc":
      "We're happy to help you with anything. Contact us by email or phone.",
    "about.ctaEmail": "Email Us",
    "about.ctaPhone": "+420 123 456 789",

