    // Tips Page
    "tips.title": "Tips for Successful Selling",
    "tips.subtitle":
      "Practical advice on how to sell your car quickly and profitably",
    "tips.photosTitle": "Quality Photography",
    "tips.photosIntro":
      "Photos are the first thing buyers see. Quality images can increase your chances of selling by up to 80%.",
    "tips.photo1Title": "Clean car from all angles",
    "tips.photo1Desc":
      "Wash and polish the car thoroughly before taking photos. Shoot from all 4 sides, front and back.",
    "tips.photo2Title": "Good lighting",
    "tips.photo2Desc":
      "Take photos in daylight, preferably outdoors. Avoid shooting at night or in a dark garage.",
    "tips.photo3Title": "Interior details",
    "tips.photo3Desc":
      "Show the dashboard, seats, steering wheel, and trunk. The interior should be clean and tidy.",
    "tips.photo4Title": "Technical details",
    "tips.photo4Desc":
      "Add photos of the engine, odometer, and any damage. Be transparent.",
    "tips.descriptionTitle": "Listing Description",
    "tips.descriptionIntro":
      "A quality description helps buyers decide faster and reduces unnecessary questions.",
    "tips.desc1Title": "Be honest",
    "tips.desc1Desc":
      "List all defects and vehicle history. Transparency builds trust and speeds up the sale.",
    "tips.desc2Title": "Technical specifications",
    "tips.desc2Desc":
      "Clearly specify year, mileage, fuel type, equipment, and service history.",
    "tips.desc3Title": "Unique features",
    "tips.desc3Desc":
      "Highlight advantages - new tires, fresh inspection, garage, service book, one owner, etc.",
    "tips.pricingTitle": "Pricing Strategy",
    "tips.pricingIntro": "The right price is key to a quick sale.",
    "tips.price1Title": "Compare with the market",
    "tips.price1Desc":
      "Look at similar listings of the same model and year. Set a competitive price.",
    "tips.price2Title": "Leave room for negotiation",
    "tips.price2Desc":
      "Buyers usually expect to negotiate. Add 5-10% above your minimum acceptable price.",
    "tips.price3Title": "Update the price",
    "tips.price3Desc":
      "If the car isn't selling, lower the price every 2-3 weeks. Respond to demand.",
    "tips.communicationTitle": "Communicating with Buyers",
    "tips.comm1Title": "Quick response",
    "tips.comm1Desc":
      "Respond to inquiries within 24 hours. Quick reactions show interest and professionalism.",
    "tips.comm2Title": "Flexible viewings",
    "tips.comm2Desc":
      "Offer several viewing times. Accommodate buyers when scheduling.",
    "tips.comm3Title": "Professional approach",
    "tips.comm3Desc":
      "Be polite, patient, and willing to answer all questions. First impressions matter.",
    "tips.mistakesTitle": "Common Seller Mistakes",
    "tips.mistake1":
      "Blurry or dark photos that don't represent the car properly",
    "tips.mistake2": "Unrealistically high price with no room for negotiation",
    "tips.mistake3":
      "Incomplete or misleading description without mentioning defects",
    "tips.mistake4": "Slow communication or unavailability by phone",
    "tips.timelineTitle": "Average Selling Time",
    "tips.timelineIntro": "Following all tips, selling typically takes:",
    "tips.timelineDays": "days (TOP listing)",
    "tips.timelineWeeks": "days (standard)",
    "tips.timelineMonth": "days (without optimization)",
    "tips.ctaTitle": "Ready to Sell?",
    "tips.ctaDesc":
      "Create a professional listing today and sell your car quickly and profitably.",
